1	/**
2	 * Image Plugin
3	 *
4	 * Implements live preview for Markdown images
5	 * Shows image preview when cursor is outside image syntax, shows source when inside
6	 */
7	
8	import { syntaxTree } from '@codemirror/language';
9	import { EditorState, Range, StateField } from '@codemirror/state';
10	import { Decoration, DecorationSet, EditorView } from '@codemirror/view';
11	import { shouldShowSource } from '../core/shouldShowSource';
12	import { mouseSelectingField } from '../core/mouseSelecting';
13	import {
14	  createImageWidget,
15	  ImageData,
16	  ImageOptions,
17	} from '../widgets/imageWidget';
18	
19	export type { ImageOptions } from '../widgets/imageWidget';
20	
21	/**
22	 * Parse image syntax
23	 *
24	 * @param text - Image syntax text
25	 * @returns Parsed image data, or null
26	 */
27	export function parseImageSyntax(text: string): ImageData | null {
28	  // Match ![alt](url) or ![alt](url "title") or ![alt](url 'title')
29	  // URL part supports parentheses (greedy match to last parenthesis)
30	  const match = text.match(/^!\[([^\]]*)\]\((.+?)(?:\s+["']([^"']+)["'])?\)$/);
31	
32	  if (!match) {
33	    return null;
34	  }
35	
36	  const [, alt, src, title] = match;
37	
38	  // Check if it's a local image
39	  const isLocal =
40	    !src.startsWith('http://') &&
41	    !src.startsWith('https://') &&
42	    !src.startsWith('data:');
43	
44	  return {
45	    src,
46	    alt,
47	    title,
48	    isLocal,
49	  };
50	}
51	
52	/**
53	 * Default options
54	 */
55	const defaultOptions: Required<ImageOptions> = {
56	  maxWidth: '100%',
57	  showAlt: true,
58	  showLoading: true,
59	  errorPlaceholder: 'Failed to load image',
60	  basePath: '',
61	};
62	
63	/**
64	 * Build image decorations
65	 */
66	function buildImageDecorations(
67	  state: EditorState,
68	  options: Required<ImageOptions>
69	): DecorationSet {
70	  const decorations: Range<Decoration>[] = [];
71	  const isDrag = state.field(mouseSelectingField, false);
72	
73	  syntaxTree(state).iterate({
74	    enter: (node) => {
75	      if (node.name === 'Image') {
76	        const from = node.from;
77	        const to = node.to;
78	
79	        // Get image syntax text
80	        const text = state.doc.sliceString(from, to);
81	        const imageData = parseImageSyntax(text);
82	
83	        if (!imageData) {
84	          return;
85	        }
86	
87	        // Decide display mode
88	        const isTouched = shouldShowSource(state, from, to);
89	
90	        if (!isTouched && !isDrag) {
91	          // Render mode: show widget
92	          const widget = createImageWidget(imageData, options);
93	
94	          decorations.push(
95	            Decoration.replace({ widget, block: true }).range(from, to)
96	          );
97	        } else {
98	          // Edit mode: add background to image line
99	          const line = state.doc.lineAt(from);
100	          decorations.push(
101	            Decoration.line({ class: 'cm-image-source' }).range(line.from)
102	          );
103	        }
104	      }
105	    },
106	  });
107	
108	  return Decoration.set(decorations.sort((a, b) => a.from - b.from), true);
109	}
110	
111	/**
112	 * Create image StateField
113	 */
114	function createImageField(
115	  options: Required<ImageOptions>
116	): StateField<DecorationSet> {
117	  return StateField.define<DecorationSet>({
118	    create(state) {
119	      return buildImageDecorations(state, options);
120	    },
121	
122	    update(deco, tr) {
123	      // Rebuild on document or config change
124	      if (tr.docChanged || tr.reconfigured) {
125	        return buildImageDecorations(tr.state, options);
126	      }
127	
128	      // Rebuild on drag state change
129	      const isDragging = tr.state.field(mouseSelectingField, false);
130	      const wasDragging = tr.startState.field(mouseSelectingField, false);
131	
132	      if (wasDragging && !isDragging) {
133	        return buildImageDecorations(tr.state, options);
134	      }
135	
136	      // Keep unchanged during drag
137	      if (isDragging) {
138	        return deco;
139	      }
140	
141	      // Rebuild on selection change
142	      if (tr.selection) {
143	        return buildImageDecorations(tr.state, options);
144	      }
145	
146	      return deco;
147	    },
148	
149	    provide: (f) => EditorView.decorations.from(f),
150	  });
151	}
152	
153	// Cache StateField instance
154	let cachedField: StateField<DecorationSet> | null = null;
155	let cachedOptions: Required<ImageOptions> | null = null;
156	
157	/**
158	 * Image plugin
159	 *
160	 * @param options - Configuration options
161	 * @returns StateField
162	 *
163	 * @example
164	 * ```typescript
165	 * import { imageField } from 'codemirror-live-markdown';
166	 *
167	 * // Use default config
168	 * extensions: [imageField()]
169	 *
170	 * // Custom config
171	 * extensions: [imageField({
172	 *   maxWidth: '600px',
173	 *   showAlt: true,
174	 *   basePath: '/assets/images/',
175	 * })]
176	 * ```
177	 */
178	export function imageField(options?: ImageOptions): StateField<DecorationSet> {
179	  const mergedOptions = { ...defaultOptions, ...options };
180	
181	  // Check if cache can be reused
182	  if (
183	    cachedField &&
184	    cachedOptions &&
185	    cachedOptions.maxWidth === mergedOptions.maxWidth &&
186	    cachedOptions.showAlt === mergedOptions.showAlt &&
187	    cachedOptions.showLoading === mergedOptions.showLoading &&
188	    cachedOptions.errorPlaceholder === mergedOptions.errorPlaceholder &&
189	    cachedOptions.basePath === mergedOptions.basePath
190	  ) {
191	    return cachedField;
192	  }
193	
194	  // Create new StateField
195	  cachedField = createImageField(mergedOptions);
196	  cachedOptions = mergedOptions;
197	
198	  return cachedField;
199	}
