1	/**
2	 * Image Widget
3	 *
4	 * Renders Markdown image preview with loading state and error handling
5	 */
6	
7	import { WidgetType } from '@codemirror/view';
8	import { loadImage } from '../utils/imageLoader';
9	
10	/**
11	 * Image data interface
12	 */
13	export interface ImageData {
14	  /** Image source URL */
15	  src: string;
16	  /** Alt text */
17	  alt: string;
18	  /** Title */
19	  title?: string;
20	  /** Whether it's a local image */
21	  isLocal: boolean;
22	}
23	
24	/**
25	 * Image options interface
26	 */
27	export interface ImageOptions {
28	  /** Max width, default '100%' */
29	  maxWidth?: string;
30	  /** Whether to show alt text, default true */
31	  showAlt?: boolean;
32	  /** Whether to show loading state, default true */
33	  showLoading?: boolean;
34	  /** Placeholder for failed image load */
35	  errorPlaceholder?: string;
36	  /** Base path for local images */
37	  basePath?: string;
38	}
39	
40	/**
41	 * Image Widget class
42	 */
43	export class ImageWidget extends WidgetType {
44	  constructor(
45	    readonly data: ImageData,
46	    readonly options: ImageOptions
47	  ) {
48	    super();
49	  }
50	
51	  /**
52	   * Check if two widgets are equal
53	   */
54	  eq(other: ImageWidget): boolean {
55	    return (
56	      other.data.src === this.data.src &&
57	      other.data.alt === this.data.alt &&
58	      other.data.title === this.data.title
59	    );
60	  }
61	
62	  /**
63	   * Render to DOM element
64	   */
65	  toDOM(): HTMLElement {
66	    const { src, alt, title } = this.data;
67	    const {
68	      maxWidth = '100%',
69	      showAlt = true,
70	      showLoading = true,
71	      errorPlaceholder = 'Failed to load image',
72	      basePath = '',
73	    } = this.options;
74	
75	    // Container
76	    const container = document.createElement('div');
77	    container.className = 'cm-image-widget';
78	
79	    // Show loading state
80	    if (showLoading) {
81	      const loading = document.createElement('div');
82	      loading.className = 'cm-image-loading';
83	      loading.innerHTML = `
84	        <span class="cm-image-spinner"></span>
85	        <span>Loading...</span>
86	      `;
87	      container.appendChild(loading);
88	    }
89	
90	    // Load image asynchronously
91	    loadImage(src, { basePath }).then((result) => {
92	      // Remove loading state
93	      const loading = container.querySelector('.cm-image-loading');
94	      if (loading) {
95	        loading.remove();
96	      }
97	
98	      if (result.loaded) {
99	        // Create image element
100	        const img = document.createElement('img');
101	        img.src = result.src;
102	        img.alt = alt;
103	        img.title = title || '';
104	        img.style.maxWidth = maxWidth;
105	        img.draggable = false;
106	
107	        container.appendChild(img);
108	
109	        // Show alt text
110	        if (showAlt && alt) {
111	          const altEl = document.createElement('div');
112	          altEl.className = 'cm-image-alt';
113	          altEl.textContent = alt;
114	          container.appendChild(altEl);
115	        }
116	      } else {
117	        // Show error state
118	        const error = document.createElement('div');
119	        error.className = 'cm-image-error';
120	        error.innerHTML = `
121	          <span class="cm-image-error-icon">⚠</span>
122	          <span>${errorPlaceholder}</span>
123	        `;
124	        container.appendChild(error);
125	      }
126	    });
127	
128	    return container;
129	  }
130	
131	  /**
132	   * Whether to ignore events
133	   *
134	   * Return false to allow click to enter edit mode
135	   */
136	  ignoreEvent(): boolean {
137	    return false;
138	  }
139	}
140	
141	/**
142	 * Create image widget
143	 */
144	export function createImageWidget(
145	  data: ImageData,
146	  options: ImageOptions
147	): ImageWidget {
148	  return new ImageWidget(data, options);
149	}
