1	/**
2	 * Image Loader Utility
3	 *
4	 * Provides async image loading, caching, and path resolution
5	 */
6	
7	/**
8	 * Loaded image info
9	 */
10	export interface LoadedImage {
11	  /** Image source URL */
12	  src: string;
13	  /** Image width */
14	  width: number;
15	  /** Image height */
16	  height: number;
17	  /** Whether load succeeded */
18	  loaded: boolean;
19	  /** Error message */
20	  error?: string;
21	}
22	
23	/**
24	 * Image load options
25	 */
26	export interface LoadImageOptions {
27	  /** Timeout in milliseconds, default 10000 */
28	  timeout?: number;
29	  /** Base path for local images */
30	  basePath?: string;
31	}
32	
33	// Image cache
34	const imageCache = new Map<string, LoadedImage>();
35	
36	// Loading promise cache (prevent duplicate requests)
37	const loadingPromises = new Map<string, Promise<LoadedImage>>();
38	
39	/**
40	 * Resolve image path
41	 *
42	 * @param src - Original path
43	 * @param basePath - Base path
44	 * @returns Resolved full path
45	 */
46	export function resolveImagePath(src: string, basePath?: string): string {
47	  // Return data URL as-is
48	  if (src.startsWith('data:')) {
49	    return src;
50	  }
51	
52	  // Return absolute URL as-is
53	  if (src.startsWith('http://') || src.startsWith('https://')) {
54	    return src;
55	  }
56	
57	  // Relative paths need resolution
58	  if (basePath) {
59	    // Remove path traversal attacks
60	    const sanitizedSrc = src.replace(/\.\.\//g, '').replace(/^\.\//g, '');
61	
62	    // Ensure basePath ends with /
63	    const normalizedBase = basePath.endsWith('/') ? basePath : basePath + '/';
64	
65	    return normalizedBase + sanitizedSrc;
66	  }
67	
68	  return src;
69	}
70	
71	/**
72	 * Load single image
73	 *
74	 * @param src - Image URL
75	 * @param options - Load options
76	 * @returns Load result
77	 */
78	export function loadImage(
79	  src: string,
80	  options: LoadImageOptions = {}
81	): Promise<LoadedImage> {
82	  const { timeout = 10000, basePath } = options;
83	
84	  // Resolve path
85	  const resolvedSrc = resolveImagePath(src, basePath);
86	
87	  // Check cache
88	  const cached = imageCache.get(resolvedSrc);
89	  if (cached) {
90	    return Promise.resolve(cached);
91	  }
92	
93	  // Check if already loading
94	  const loading = loadingPromises.get(resolvedSrc);
95	  if (loading) {
96	    return loading;
97	  }
98	
99	  // Create load promise
100	  const promise = new Promise<LoadedImage>((resolve) => {
101	    const img = new Image();
102	    let timeoutId: ReturnType<typeof setTimeout> | null = null;
103	    let resolved = false;
104	
105	    const cleanup = () => {
106	      if (timeoutId) {
107	        clearTimeout(timeoutId);
108	        timeoutId = null;
109	      }
110	      loadingPromises.delete(resolvedSrc);
111	    };
112	
113	    const handleSuccess = () => {
114	      if (resolved) return;
115	      resolved = true;
116	      cleanup();
117	
118	      const result: LoadedImage = {
119	        src: resolvedSrc,
120	        width: img.width,
121	        height: img.height,
122	        loaded: true,
123	      };
124	
125	      imageCache.set(resolvedSrc, result);
126	      resolve(result);
127	    };
128	
129	    const handleError = (error: string) => {
130	      if (resolved) return;
131	      resolved = true;
132	      cleanup();
133	
134	      const result: LoadedImage = {
135	        src: resolvedSrc,
136	        width: 0,
137	        height: 0,
138	        loaded: false,
139	        error,
140	      };
141	
142	      // Don't cache failed results, allow retry
143	      resolve(result);
144	    };
145	
146	    // Set timeout
147	    timeoutId = setTimeout(() => {
148	      handleError(`Image load timeout after ${timeout}ms`);
149	    }, timeout);
150	
151	    img.onload = handleSuccess;
152	    img.onerror = () => handleError('Image load failed');
153	
154	    // Start loading
155	    img.src = resolvedSrc;
156	  });
157	
158	  loadingPromises.set(resolvedSrc, promise);
159	  return promise;
160	}
161	
162	/**
163	 * Preload multiple images
164	 *
165	 * @param srcs - Image URL array
166	 * @param options - Load options
167	 * @returns Load results for all images
168	 */
169	export async function preloadImages(
170	  srcs: string[],
171	  options: LoadImageOptions = {}
172	): Promise<LoadedImage[]> {
173	  // Load all images in parallel
174	  const promises = srcs.map((src) => loadImage(src, options));
175	  return Promise.all(promises);
176	}
177	
178	/**
179	 * Clear image cache
180	 */
181	export function clearImageCache(): void {
182	  imageCache.clear();
183	}
