1	/**
2	 * Link Plugin
3	 *
4	 * Implements live preview for Markdown links
5	 * Hides URL part when cursor is outside link, shows only link text
6	 * Supports standard links and Wiki links
7	 */
8	
9	import { syntaxTree } from '@codemirror/language';
10	import { Range } from '@codemirror/state';
11	import {
12	  Decoration,
13	  DecorationSet,
14	  EditorView,
15	  ViewPlugin,
16	  ViewUpdate,
17	} from '@codemirror/view';
18	import { shouldShowSource } from '../core/shouldShowSource';
19	import { mouseSelectingField } from '../core/mouseSelecting';
20	import { createLinkWidget, LinkData, LinkOptions } from '../widgets/linkWidget';
21	
22	export type { LinkOptions } from '../widgets/linkWidget';
23	
24	/**
25	 * Parse standard link syntax
26	 *
27	 * @param text - Link syntax text
28	 * @returns Parsed link data, or null
29	 */
30	export function parseLinkSyntax(text: string): LinkData | null {
31	  // Exclude image syntax
32	  if (text.startsWith('!')) {
33	    return null;
34	  }
35	
36	  // Match [text](url) or [text](url "title") or [text](url 'title')
37	  const match = text.match(/^\[([^\]]*)\]\((.+?)(?:\s+["']([^"']+)["'])?\)$/);
38	
39	  if (!match) {
40	    return null;
41	  }
42	
43	  const [, linkText, url, title] = match;
44	
45	  return {
46	    text: linkText,
47	    url,
48	    title,
49	    isWikiLink: false,
50	  };
51	}
52	
53	/**
54	 * Parse Wiki link syntax
55	 *
56	 * @param text - Wiki link syntax text
57	 * @returns Parsed link data, or null
58	 */
59	export function parseWikiLink(text: string): LinkData | null {
60	  // Match [[target]] or [[target|display]]
61	  const match = text.match(/^\[\[([^\]|]+)(?:\|([^\]]+))?\]\]$/);
62	
63	  if (!match) {
64	    return null;
65	  }
66	
67	  const [, target, display] = match;
68	
69	  return {
70	    text: display || target,
71	    url: target,
72	    isWikiLink: true,
73	  };
74	}
75	
76	/**
77	 * Wiki link regex
78	 */
79	const WIKI_LINK_REGEX = /\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g;
80	
81	/**
82	 * Default options
83	 */
84	const defaultOptions: Required<LinkOptions> = {
85	  openInNewTab: true,
86	  onWikiLinkClick: undefined as unknown as (link: string) => void,
87	  showPreview: false,
88	};
89	
90	/**
91	 * Parent node types to skip (handled by other plugins)
92	 */
93	const SKIP_PARENT_TYPES = new Set(['FencedCode', 'CodeBlock', 'InlineCode']);
94	
95	/**
96	 * Build link decorations
97	 */
98	function buildLinkDecorations(
99	  view: EditorView,
100	  options: Required<LinkOptions>
101	): DecorationSet {
102	  const decorations: Range<Decoration>[] = [];
103	  const state = view.state;
104	  const isDrag = state.field(mouseSelectingField, false);
105	
106	  // Collect ranges to skip (code blocks, inline code, etc.)
107	  const skipRanges: Array<{ from: number; to: number }> = [];
108	  syntaxTree(state).iterate({
109	    enter: (node) => {
110	      if (SKIP_PARENT_TYPES.has(node.name)) {
111	        skipRanges.push({ from: node.from, to: node.to });
112	      }
113	    },
114	  });
115	
116	  // Check if position is in skip range
117	  const isInSkipRange = (from: number, to: number) => {
118	    return skipRanges.some((r) => from >= r.from && to <= r.to);
119	  };
120	
121	  // Process standard links
122	  syntaxTree(state).iterate({
123	    enter: (node) => {
124	      if (node.name === 'Link') {
125	        // Skip links inside code blocks
126	        if (isInSkipRange(node.from, node.to)) {
127	          return;
128	        }
129	        const from = node.from;
130	        const to = node.to;
131	
132	        // Get link syntax text
133	        const text = state.doc.sliceString(from, to);
134	        const linkData = parseLinkSyntax(text);
135	
136	        if (!linkData) {
137	          return;
138	        }
139	
140	        // Decide display mode
141	        const isTouched = shouldShowSource(state, from, to);
142	
143	        if (!isTouched && !isDrag) {
144	          // Render mode: show widget
145	          const widget = createLinkWidget(linkData, options);
146	
147	          decorations.push(Decoration.replace({ widget }).range(from, to));
148	        } else {
149	          // Edit mode: add background mark
150	          decorations.push(
151	            Decoration.mark({ class: 'cm-link-source' }).range(from, to)
152	          );
153	        }
154	      }
155	    },
156	  });
157	
158	  // Process Wiki links (Lezer doesn't support by default, need manual matching)
159	  const docText = state.doc.toString();
160	  let match: RegExpExecArray | null;
161	
162	  // Reset regex
163	  WIKI_LINK_REGEX.lastIndex = 0;
164	
165	  while ((match = WIKI_LINK_REGEX.exec(docText)) !== null) {
166	    const from = match.index;
167	    const to = from + match[0].length;
168	
169	    // Skip Wiki links inside code blocks
170	    if (isInSkipRange(from, to)) {
171	      continue;
172	    }
173	
174	    const wikiData = parseWikiLink(match[0]);
175	    if (!wikiData) {
176	      continue;
177	    }
178	
179	    // Decide display mode
180	    const isTouched = shouldShowSource(state, from, to);
181	
182	    if (!isTouched && !isDrag) {
183	      // Render mode: show widget
184	      const widget = createLinkWidget(wikiData, options);
185	
186	      decorations.push(Decoration.replace({ widget }).range(from, to));
187	    } else {
188	      // Edit mode: add background mark
189	      decorations.push(
190	        Decoration.mark({ class: 'cm-link-source cm-wikilink-source' }).range(
191	          from,
192	          to
193	        )
194	      );
195	    }
196	  }
197	
198	  return Decoration.set(decorations.sort((a, b) => a.from - b.from), true);
199	}
200	
201	/**
202	 * Link plugin
203	 *
204	 * @param options - Configuration options
205	 * @returns ViewPlugin
206	 *
207	 * @example
208	 * ```typescript
209	 * import { linkPlugin } from 'codemirror-live-markdown';
210	 *
211	 * // Use default config
212	 * extensions: [linkPlugin()]
213	 *
214	 * // Custom config
215	 * extensions: [linkPlugin({
216	 *   openInNewTab: true,
217	 *   onWikiLinkClick: (link) => {
218	 *     router.push(`/wiki/${link}`);
219	 *   },
220	 * })]
221	 * ```
222	 */
223	export function linkPlugin(
224	  options?: LinkOptions
225	): ViewPlugin<{
226	  decorations: DecorationSet;
227	  update(update: ViewUpdate): void;
228	}> {
229	  const mergedOptions = { ...defaultOptions, ...options };
230	
231	  return ViewPlugin.fromClass(
232	    class {
233	      decorations: DecorationSet;
234	
235	      constructor(view: EditorView) {
236	        this.decorations = buildLinkDecorations(view, mergedOptions);
237	      }
238	
239	      update(update: ViewUpdate) {
240	        // Rebuild on document or config change
241	        if (update.docChanged || update.viewportChanged) {
242	          this.decorations = buildLinkDecorations(update.view, mergedOptions);
243	          return;
244	        }
245	
246	        // Rebuild on drag state change
247	        const isDragging = update.state.field(mouseSelectingField, false);
248	        const wasDragging = update.startState.field(mouseSelectingField, false);
249	
250	        if (wasDragging && !isDragging) {
251	          this.decorations = buildLinkDecorations(update.view, mergedOptions);
252	          return;
253	        }
254	
255	        // Keep unchanged during drag
256	        if (isDragging) {
257	          return;
258	        }
259	
260	        // Rebuild on selection change
261	        if (update.selectionSet) {
262	          this.decorations = buildLinkDecorations(update.view, mergedOptions);
263	        }
264	      }
265	    },
266	    {
267	      decorations: (v) => v.decorations,
268	    }
269	  );
270	}
